-- Create "teacher_absences" table
CREATE TABLE "teacher_absences" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), "from_date" date NOT NULL, "to_date" date NOT NULL, "from_half" character varying NOT NULL DEFAULT 'forenoon', "to_half" character varying NOT NULL DEFAULT 'afternoon', "status" character varying NOT NULL DEFAULT 'recorded', "reason" text NULL, "withdrawn_at" timestamptz NULL, "withdrawal_reason" text NULL, "teacher_id" uuid NOT NULL, "recorded_by" uuid NULL, "withdrawn_by" uuid NULL, PRIMARY KEY ("id"), CONSTRAINT "teacher_absences_persons_recorder" FOREIGN KEY ("recorded_by") REFERENCES "persons" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "teacher_absences_persons_withdrawer" FOREIGN KEY ("withdrawn_by") REFERENCES "persons" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "teacher_absences_teachers_teacher" FOREIGN KEY ("teacher_id") REFERENCES "teachers" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "teacher_absences_window_ordered" CHECK ((to_date > from_date) OR ((to_date = from_date) AND (((from_half)::text = 'forenoon'::text) OR ((to_half)::text = 'afternoon'::text)))), CONSTRAINT "teacher_absences_withdrawal_dated" CHECK ((((status)::text = 'withdrawn'::text) AND (withdrawn_at IS NOT NULL)) OR (((status)::text <> 'withdrawn'::text) AND (withdrawn_at IS NULL) AND (withdrawn_by IS NULL) AND (withdrawal_reason IS NULL))));
-- Create index "teacherabsence_from_date_to_date" to table: "teacher_absences"
CREATE INDEX "teacherabsence_from_date_to_date" ON "teacher_absences" ("from_date", "to_date");
-- Create index "teacherabsence_teacher_id_from_date" to table: "teacher_absences"
CREATE INDEX "teacherabsence_teacher_id_from_date" ON "teacher_absences" ("teacher_id", "from_date");
-- Create index "teacherabsence_teacher_id_from_date_from_half_to_date_to_half" to table: "teacher_absences"
CREATE UNIQUE INDEX "teacherabsence_teacher_id_from_date_from_half_to_date_to_half" ON "teacher_absences" ("teacher_id", "from_date", "from_half", "to_date", "to_half") WHERE ((status)::text = 'recorded'::text);
